"""Local effect sink for a revocation-barrier experiment, NOT a production service.
A committed SQLite report row is the WHOLE effect. No later external delivery.
Linux SO_PEERCRED authenticates root as fixture authority; worker UID is 65534.
The sink, host kernel and filesystem are trusted. Only fixed test clients run.
"""
from __future__ import annotations
import json
import os
from pathlib import Path
import socket
import sqlite3
import struct
import sys

LIMIT = 16384
WORKER = 65534


def identity() -> dict:
    status = Path('/proc/self/status').read_text()
    return dict(uid=os.getuid(), gid=os.getgid(), groups=os.getgroups(),
                cap_eff=next(s.split()[1] for s in status.splitlines()
                             if s.startswith('CapEff:')), optimize=sys.flags.optimize)


def read_message(conn: socket.socket) -> dict:
    with conn.makefile('rb') as stream:
        raw = stream.readline(LIMIT + 1)
    if not raw:
        raise EOFError('response/request absent; outcome not inferred')
    if len(raw) > LIMIT or not raw.endswith(b'\n'):
        raise ValueError('invalid frame')
    data = json.loads(raw)
    if type(data) is not dict:
        raise ValueError('object required')
    return data


def rpc(path: Path, request: dict) -> dict:
    with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as conn:
        conn.settimeout(3)
        conn.connect(str(path))
        conn.sendall((json.dumps(request, sort_keys=True) + '\n').encode())
        return read_message(conn)


def connect(path: Path, readonly: bool = False) -> sqlite3.Connection:
    target = path.resolve().as_uri() + '?mode=ro' if readonly else str(path)
    db = sqlite3.connect(target, uri=readonly, isolation_level=None, timeout=3)
    db.row_factory = sqlite3.Row
    return db


def observe(path: Path) -> dict:
    db = connect(path, True)
    try:
        db.execute('BEGIN')
        return {table: [dict(r) for r in db.execute('SELECT * FROM ' + table + ' ORDER BY 1')]
                for table in ('state', 'grants', 'effects', 'events')}
    finally:
        db.close()


def dispatch(db: sqlite3.Connection, name: str, req: dict, peer: int) -> dict:
    op = req.get('op')
    if op in ('INSTALL', 'FENCE', 'STOP') and peer != 0:
        return {'status': 'DENY_AUTHORITY'}
    if op == 'DO' and peer != WORKER:
        return {'status': 'DENY_WORKER'}
    if op == 'PING':
        return {'status': 'READY', 'identity': identity()}
    if op == 'STOP':
        return {'status': 'STOPPED'}
    floor = db.execute('SELECT minimum_epoch FROM state').fetchone()[0]
    if op == 'FENCE':
        new, rid = req.get('minimum_epoch'), req.get('revocation_id')
        if type(new) is not int or not 1 <= new < 2**60 or type(rid) is not str:
            return {'status': 'BAD_REQUEST'}
        floor = max(floor, new)
        db.execute('UPDATE state SET minimum_epoch=?', (floor,))
        return {'status': 'FENCED', 'minimum_epoch': floor, 'revocation_id': rid}
    if op in ('INSTALL', 'DO'):
        fields = ('ticket', 'task', 'sink', 'payload')
        if any(type(req.get(k)) is not str or not 1 <= len(req[k]) <= 1024 for k in fields):
            return {'status': 'BAD_REQUEST'}
        epoch = req.get('epoch')
        if type(epoch) is not int or not 1 <= epoch < 2**60:
            return {'status': 'BAD_REQUEST'}
        if req['sink'] != name or req['task'] != 'T':
            return {'status': 'DENY_SCOPE'}
        if epoch < floor:
            return {'status': 'DENY_STALE', 'minimum_epoch': floor}
        values = (req['ticket'], epoch, req['task'], name, req['payload'])
        g = db.execute('SELECT * FROM grants WHERE ticket=?', (req['ticket'],)).fetchone()
        if op == 'INSTALL':
            if g is not None:
                return {'status': 'INSTALLED' if tuple(g) == values else 'DENY_REBIND'}
            db.execute('INSERT INTO grants VALUES (?,?,?,?,?)', values)
            return {'status': 'INSTALLED'}
        if g is None or tuple(g) != values:
            return {'status': 'DENY_BINDING'}
        old = db.execute('SELECT * FROM effects WHERE ticket=?', (req['ticket'],)).fetchone()
        if old is not None:
            return {'status': 'REPLAY_NO_NEW_EFFECT'}
        # Epoch check and actual effect are in the SAME sink transaction.
        db.execute('INSERT INTO effects VALUES (?,?,?,?,?)', values)
        return {'status': 'COMMITTED'}
    return {'status': 'BAD_REQUEST'}


def serve(directory: Path, name: str) -> None:
    os.umask(0o077)
    private = directory / 'private'
    private.mkdir(mode=0o700, exist_ok=True)
    db = connect(private / 'sink.db')
    db.execute('PRAGMA synchronous=FULL')
    db.executescript('''
      CREATE TABLE IF NOT EXISTS state(minimum_epoch INTEGER NOT NULL);
      INSERT INTO state SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM state);
      CREATE TABLE IF NOT EXISTS grants(ticket TEXT PRIMARY KEY, epoch INTEGER,
        task TEXT, sink TEXT, payload TEXT);
      CREATE TABLE IF NOT EXISTS effects(ticket TEXT PRIMARY KEY, epoch INTEGER,
        task TEXT, sink TEXT, payload TEXT);
      CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY, op TEXT,
        peer_uid INTEGER, status TEXT, detail TEXT);
    ''')
    address = directory / 'rpc.sock'
    address.unlink(missing_ok=True)  # only the supervisor restarts this fixed sink
    try:
        with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as server:
            server.bind(str(address))
            address.chmod(0o666)
            server.listen(8)
            print(json.dumps({'ready': name, 'identity': identity()}), flush=True)
            done = False
            while not done:
                conn, _ = server.accept()
                with conn:
                    conn.settimeout(3)
                    peer = struct.unpack('3i', conn.getsockopt(socket.SOL_SOCKET,
                                             socket.SO_PEERCRED, 12))[1]
                    try:
                        req = read_message(conn)
                        db.execute('BEGIN IMMEDIATE')
                        out = dispatch(db, name, req, peer)
                        seq = db.execute('INSERT INTO events(op,peer_uid,status,detail) VALUES (?,?,?,?)',
                            (str(req.get('op')), peer, out['status'],
                             json.dumps(req, sort_keys=True))).lastrowid
                        db.execute('COMMIT')
                        out |= {'sink': name, 'peer_uid': peer, 'event_seq': seq}
                        # Root-only fault injection: commit fence, die BEFORE reply.
                        if peer == 0 and req.get('crash_after_commit') and out['status'] == 'FENCED':
                            os._exit(91)
                        conn.sendall((json.dumps(out, sort_keys=True) + '\n').encode())
                        done = out['status'] == 'STOPPED'
                    except (ValueError, sqlite3.Error) as e:
                        if db.in_transaction:
                            db.execute('ROLLBACK')
                        conn.sendall((json.dumps({'status': 'ERROR', 'kind': type(e).__name__}) + '\n').encode())
                    except (OSError, EOFError):
                        if db.in_transaction:
                            db.execute('ROLLBACK')
    finally:
        db.close()
        address.unlink(missing_ok=True)


if __name__ == '__main__':
    if sys.argv[1] == 'serve':
        serve(Path(sys.argv[2]), sys.argv[3])
    elif sys.argv[1] == 'client':
        response = rpc(Path(sys.argv[2]), json.load(sys.stdin))
        print(json.dumps({'identity': identity(), 'response': response}, sort_keys=True))
    elif sys.argv[1] == 'tamper':
        try:
            with Path(sys.argv[2]).open('ab') as f:
                f.write(b'FIXED TEST MUTATION')
            result = {'changed': True}
        except OSError as e:
            result = {'changed': False, 'errno': e.errno}
        print(json.dumps({'identity': identity(), 'result': result}, sort_keys=True))
    else:
        raise SystemExit('unknown fixed mode')
```
